CREATE OR REPLACE VIEW `vwleadcalls` AS select `l`.`legacy_id` AS `legacy_id`,`c`.`numero_chiamato` AS `numero_chiamato`,`c`.`id` AS `id` from (`leads` `l` join `calls` `c` on((`c`.`numero_chiamato` = `l`.`telefono`))) union select `l`.`legacy_id` AS `legacy_id`,`c`.`numero_chiamato` AS `numero_chiamato`,`c`.`id` AS `id` from (`leads` `l` join `calls` `c` on((`c`.`numero_chiamato` = `l`.`telefono2`))) where (`l`.`telefono2` is not null) union select `l`.`legacy_id` AS `legacy_id`,`c`.`numero_chiamato` AS `numero_chiamato`,`c`.`id` AS `id` from (`leads` `l` join `calls` `c` on((`c`.`numero_chiamato` = `l`.`telefono3`))) where (`l`.`telefono3` is not null) union select `l`.`legacy_id` AS `legacy_id`,`c`.`numero_chiamato` AS `numero_chiamato`,`c`.`id` AS `id` from (`leads` `l` join `calls` `c` on((`c`.`numero_chiamato` = `l`.`telefono4`))) where (`l`.`telefono4` is not null)
